<script setup lang="ts">
import { computed, onScopeDispose, shallowRef, watch } from 'vue'
import { useRouter } from 'vue-router'
import { ElButton } from 'element-plus'
import ImportPreview from './ImportPreview.vue'
import { errorMessage, request } from '../../api/client'
import { readNodeSummaries } from '../../api/nodes'
import { useProfiles } from '../../layout/useProfiles'
import type { BindingChoice, ConfigImportPreview, DraftView, NodeSummary, SourceView } from '../../types/domain'
const router=useRouter(),catalog=useProfiles(),text=shallowRef(''),filename=shallowRef(''),preview=shallowRef<ConfigImportPreview|null>(null),choices=shallowRef<Record<string,BindingChoice>>({}),nodes=shallowRef<NodeSummary[]>([]),sources=shallowRef<SourceView[]>([])
const busy=shallowRef(false),error=shallowRef(''),created=shallowRef<DraftView|null>(null),step=computed(()=>created.value?3:preview.value?2:1)
let sequence=0,fileSequence=0,read:AbortController|null=null,disposed=false
const lifetime=new AbortController()
watch(text,()=>{sequence++;read?.abort();preview.value=null;choices.value={};busy.value=false;error.value=''}, {flush:'sync'})
onScopeDispose(()=>{disposed=true;sequence++;fileSequence++;read?.abort();lifetime.abort();text.value='';preview.value=null})
async function fileChanged(event:Event){const file=(event.target as HTMLInputElement).files?.[0],current=++fileSequence;if(!file)return;if(file.size>10*1024*1024){error.value='配置文件不能超过 10 MiB';return}try{const value=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());if(current===fileSequence&&!disposed){text.value=value;filename.value=file.name}}catch{if(current===fileSequence&&!disposed)error.value='无法读取 UTF-8 配置文件'}}
async function parse(){const current=++sequence;read?.abort();read=new AbortController();busy.value=true;error.value='';try{const result=await request<ConfigImportPreview>('/imports/preview',{method:'POST',body:{yaml:text.value},signal:read.signal});const [pool,list]=await Promise.all([readNodeSummaries(read.signal),request<SourceView[]>('/sources',{signal:read.signal})]);if(current===sequence&&!disposed){preview.value=result;nodes.value=pool;sources.value=list;choices.value=Object.fromEntries(result.nodes.map(node=>[node.id,{mode:'LOCAL',remoteNodeId:null}]))}}catch(cause){if(current===sequence&&!disposed)error.value=errorMessage(cause)}finally{if(current===sequence)busy.value=false}}
async function confirm(){if(!preview.value||busy.value)return;busy.value=true;error.value='';try{const draft=await request<DraftView>(`/imports/${preview.value.id}/confirm`,{method:'POST',body:{choices:choices.value},signal:lifetime.signal});if(disposed)return;created.value=draft;await catalog.reload(lifetime.signal);await router.push(`/profiles/${draft.profileId}`)}catch(cause){if(!disposed)error.value=errorMessage(cause)}finally{busy.value=false}}
</script>
<template><header class="page-heading"><p class="eyebrow">MIGRATE YOUR CONFIGURATION</p><h1>导入完整配置</h1><p class="muted">读取 Clash / Mihomo YAML，保留本地节点，创建独立的新方案草稿。</p></header><ol class="import-steps"><li :class="{active:step===1}">1 · 读取配置</li><li :class="{active:step===2}">2 · 预览与节点关联</li><li :class="{active:step===3}">3 · 创建草稿</li></ol><p v-if="error" class="error import-error" role="alert">{{ error }}</p><section v-if="created" class="panel panel-body"><h2>新方案草稿已创建</h2><p>导入没有替换已有方案，配置尚未发布。</p><ElButton @click="router.push(`/profiles/${created.profileId}`)">打开新方案</ElButton></section><ImportPreview v-else-if="preview" :preview="preview" :choices="choices" :nodes="nodes" :sources="sources" :busy="busy" @choose="(id,choice)=>choices={...choices,[id]:choice}" @confirm="confirm" @back="preview=null" /><section v-else class="panel"><header class="panel-header"><div><h2>读取 YAML 文件</h2><p class="muted">不支持的字段会明确列出，完整原文另行保留。</p></div></header><div class="panel-body form-grid"><label>选择配置文件<input type="file" accept=".yaml,.yml,text/yaml,application/yaml" aria-label="完整配置文件" @change="fileChanged"></label><p v-if="filename" class="muted">{{ filename }}</p><label>或粘贴完整配置<textarea v-model="text" aria-label="完整配置 YAML" rows="16" spellcheck="false" class="import-yaml" placeholder="mixed-port: 7890&#10;proxies: …&#10;proxy-groups: …&#10;rules: …"></textarea></label><div class="dialog-actions"><ElButton type="primary" :loading="busy" :disabled="!text.trim()" @click="parse">解析并预览</ElButton></div></div></section></template>
<style scoped>.import-steps{display:flex;gap:24px;list-style:none;padding:0;margin:0 0 24px;color:var(--muted);font-size:12px}.import-steps .active{color:var(--accent);font-weight:600}.import-error{margin-bottom:20px}.import-yaml{font-family:monospace;white-space:pre;overflow:auto}@media(max-width:600px){.import-steps{gap:10px;font-size:10px}}</style>
